<script setup>import {money,date} from '../api/client.js';defineProps({booking:Object});defineEmits(['view']);</script><template><article class="ticket-card card"><span class="bus-thumb">🚌</span><div class="ticket-code"><b>{{booking.trip.route}}</b><small>{{date(booking.trip.departureTime)}}</small></div><div><b>Ghế {{booking.tickets.map(t=>t.seat).join(', ')}}</b></div><div class="ticket-price"><b>{{money(booking.totalAmount)}}</b><span class="status" :class="booking.status">{{booking.status==='PAID'?'Đã thanh toán':booking.status==='PENDING_PAYMENT'?'Chờ thanh toán':'Hết hạn'}}</span></div><div class="ticket-actions-inline"><button @click="$emit('view',booking)">Xem vé</button></div></article></template>
